+    [Parameter] public ApplicationFormState State { get; set; } = default!;
+    [Parameter] public EventCallback OnNext { get; set; }
+    [Parameter] public EventCallback OnBack { get; set; }
+
+    private bool showErrors;
+
+    private void AddReference()
+    {
+        if (State.References.Count < 3)
+        {
+            State.References.Add(new ReferenceModel());
+        }
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (State.References.Count > 2)
+        {
+            State.References.RemoveAt(index);
+        }
+    }
+
+    private async Task HandleNext()
+    {
+        showErrors = true;
+        for (int i = 0; i < Math.Min(2, State.References.Count); i++)
+        {
+            if (string.IsNullOrWhiteSpace(State.References[i].Name) || string.IsNullOrWhiteSpace(State.References[i].Email))
+            {
+                return;
+            }
+        }
+        await OnNext.InvokeAsync();
+    }
+
+    private async Task HandleBack()
+    {
+        await OnBack.InvokeAsync();
+    }
+}
+

