+@page "/apply"
+@rendermode InteractiveServer
+@inject ApplicationFormState State
+@inject IApplicationService ApplicationService
+
+<PageTitle>Job Application</PageTitle>
+
+<div class="apply-container">
+    <h1>Job Application</h1>
+
+    <StepIndicator CurrentStep="State.CurrentStep"
+                   CompletedSteps="State.CompletedSteps"
+                   OnStepClicked="GoToStep" />
+
+    <div class="step-content">
+        @switch (State.CurrentStep)
+        {
+            case 1:
+                <PersonalInfoStep State="State"
+                                  OnNext="Next"
+                                  EmailError="@emailError"
+                                  OnValidateAndNext="ValidateEmailAndNext" />
+                break;
+            case 2:
+                <WorkHistoryStep State="State"
+                                 OnNext="Next"
+                                 OnBack="Back" />
+                break;
+            case 3:
+                <ReferencesStep State="State"
+                                OnNext="Next"
+                                OnBack="Back" />
+                break;
+            case 4:
+                <CoverLetterStep State="State"
+                                 OnNext="Next"
+                                 OnBack="Back" />
+                break;
+            case 5:
+                <ReviewStep State="State"
+                            OnSubmit="Submit"
+                            OnBack="Back"
+                            OnEditStep="GoToStep"
+                            IsSubmitting="isSubmitting" />
+                break;
+        }
+    </div>
+</div>
+
+@code {
+    private string? emailError;
+    private bool isSubmitting;
+
+    private void GoToStep(int step)
+    {
+        if (step <= State.CurrentStep || State.CompletedSteps.Contains(step) || State.CompletedSteps.Contains(step - 1))
+        {
+            State.CurrentStep = step;
+        }
+    }
+
+    private void Next()
+    {
+        State.CompletedSteps.Add(State.CurrentStep);
+        if (State.CurrentStep < ApplicationFormState.TotalSteps)
+        {
+            State.CurrentStep++;
+        }
+    }
+
+    private void Back()
+    {
+        if (State.CurrentStep > 1)
+        {
+            State.CurrentStep--;
+        }
+    }
+
+    private async Task ValidateEmailAndNext()
+    {
+        emailError = null;
+        var isValid = await ApplicationService.ValidateEmailAsync(State.Email);
+        if (!isValid)
+        {
+            emailError = "Please enter a valid email address.";
+            return;
+        }
+        Next();
+    }
+
+    private async Task Submit()
+    {
+        isSubmitting = true;
+        StateHasChanged();
+
+        var application = new JobApplication(
+            new PersonalInfo(State.FullName, State.Email, State.Phone, State.Address),
+            new WorkHistory(State.WorkEntries.Select(w => new WorkEntry(
+                w.Company, w.Title, w.StartDate ?? DateTime.Today, w.EndDate, w.Description)).ToList()),
+            State.References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+            State.CoverLetter
+        );
+
+        State.ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
+        State.IsSubmitted = true;
+        State.CompletedSteps.Add(5);
+        isSubmitting = false;
+    }
+}
+

