+    <input id="email" type="email" @bind="State.Email" @bind:event="oninput" placeholder="Enter your email" />
+    @if (showErrors && string.IsNullOrWhiteSpace(State.Email))
+    {
+        <span class="validation-error">Email is required.</span>
+    }
