+    [Parameter] public EventCallback OnValidateAndNext { get; set; }
+
+    private bool showErrors;
+
+    private async Task HandleNext()
+    {
+        showErrors = true;
+        if (string.IsNullOrWhiteSpace(State.FullName) || string.IsNullOrWhiteSpace(State.Email))
+        {
+            return;
+        }
+        await OnValidateAndNext.InvokeAsync();
+    }
+}
