+<h2>Work History</h2>
+
+@for (int i = 0; i < State.WorkEntries.Count; i++)
+{
+    var index = i;
+    var entry = State.WorkEntries[index];
+
+    <div class="work-entry-card">
+        <h3>Position @(index + 1)</h3>
+
+        <div class="form-group">
+            <label>Company <span class="required">*</span></label>
+            <input type="text" @bind="entry.Company" @bind:event="oninput" placeholder="Company name" />
+            @if (showErrors && index == 0 && string.IsNullOrWhiteSpace(entry.Company))
+            {
+                <span class="validation-error">Company is required.</span>
+            }
+        </div>
+
+        <div class="form-group">
+            <label>Job Title <span class="required">*</span></label>
+            <input type="text" @bind="entry.Title" @bind:event="oninput" placeholder="Job title" />
+            @if (showErrors && index == 0 && string.IsNullOrWhiteSpace(entry.Title))
+            {
+                <span class="validation-error">Job title is required.</span>
+            }
+        </div>
+
+        <div class="form-row">
+            <div class="form-group">
+                <label>Start Date</label>
+                <input type="date" @bind="entry.StartDate" />
+            </div>
+
+            <div class="form-group">
+                <label>
+                    <input type="checkbox" @bind="entry.IsCurrent" /> I currently work here
+                </label>
+            </div>
+
+            <div class="form-group">
+                <label>End Date</label>
+                <input type="date" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
+            </div>
+        </div>
+
+        <div class="form-group">
+            <label>Description</label>
+            <textarea @bind="entry.Description" @bind:event="oninput" placeholder="Describe your responsibilities..." rows="3"></textarea>
+        </div>
+
+        @if (State.WorkEntries.Count > 1)
+        {
+            <button class="btn-danger" @onclick="() => RemoveEntry(index)">Remove</button>
+        }
+    </div>
+}
+
+<button class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>
+
+<div class="form-actions">
+    <button class="btn-secondary" @onclick="HandleBack">Back</button>
+    <button class="btn-primary" @onclick="HandleNext">Next</button>
+</div>
+
+@code {
+    [Parameter] public ApplicationFormState State { get; set; } = default!;
+    [Parameter] public EventCallback OnNext { get; set; }
+    [Parameter] public EventCallback OnBack { get; set; }
+
+    private bool showErrors;
+
+    private void AddEntry()
+    {
+        State.WorkEntries.Add(new WorkEntryModel());
+    }
+
+    private void RemoveEntry(int index)
+    {
+        State.WorkEntries.RemoveAt(index);
+    }
+
+    private async Task HandleNext()
+    {
+        showErrors = true;
+        var first = State.WorkEntries[0];
+        if (string.IsNullOrWhiteSpace(first.Company) || string.IsNullOrWhiteSpace(first.Title))
+        {
+            return;
+        }
+        await OnNext.InvokeAsync();
+    }
+
+    private async Task HandleBack()
+    {
+        await OnBack.InvokeAsync();
+    }
+}
+

